From d36e58fe5943aaa900a19979770e7bc7ddc0a7ca Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 29 Oct 2026 15:06:40 +0100
Subject: [PATCH] faces: Close open label editors when the sensors page is
 shown again

The sensors page is created once and reused every time the settings are
opened, so a label editor left open stayed open, with stale text, the next
time. Close all label editors when the page is shown again.

BUG: 442694
---
 faces/ConfigSensors.qml  |  5 +++++
 faces/import/Choices.qml | 13 +++++++++++--
 2 files changed, 16 insertions(+), 2 deletions(-)

diff --git a/faces/ConfigSensors.qml b/faces/ConfigSensors.qml
index 86c0c6ba..0cf6ad15 100644
--- a/faces/ConfigSensors.qml
+++ b/faces/ConfigSensors.qml
@@ -88,8 +88,13 @@ ColumnLayout {
     // When the ui is open in systemsettings and the page is switched around,
     // it gets reparented to null. use this to reload its config every time the
     // page is current again. So any non saved change to the sensor list gets forgotten.
+    // The page is also reused when the settings are opened again, so close any
+    // label editor left open last time.
     onParentChanged: {
         if (parent) {
+            totalChoice.stopEditing()
+            highPriorityChoice.stopEditing()
+            lowPriorityChoice.stopEditing()
             loadConfig()
         }
     }
diff --git a/faces/import/Choices.qml b/faces/import/Choices.qml
index 18988393..e0a75417 100644
--- a/faces/import/Choices.qml
+++ b/faces/import/Choices.qml
@@ -30,6 +30,13 @@ Control {
     signal colorForSensorGenerated(string sensorId, color color)
     signal sensorLabelChanged(string sensorId, string label)

+    // Close any open label editor, e.g. when the page is shown again.
+    function stopEditing() {
+        for (let i = 0; i < repeater.count; ++i) {
+            repeater.itemAt(i).editing = false;
+        }
+    }
+
     onSelectedChanged: {
         if (!control.selected) {
             return;
@@ -96,6 +103,7 @@ Control {
                 implicitWidth: Math.min(layout.implicitWidth + Kirigami.Units.smallSpacing * 2,
                                         control.width - control.leftPadding - control.rightPadding)
                 readonly property int position: index
+                property bool editing: false
                 Rectangle {
                     id: delegateContents
                     z: 10
@@ -236,7 +244,7 @@ Control {
                                 icon.height: Kirigami.Units.iconSizes.small
                                 Layout.preferredWidth: Kirigami.Units.iconSizes.smallMedium
                                 Layout.preferredHeight: Kirigami.Units.iconSizes.smallMedium
-                                onClicked: layout.state = "editing"
+                                onClicked: delegate.editing = true
                             }
                             ToolButton {
                                 id: removeButton
@@ -275,7 +283,7 @@ Control {
                                             text = ""
                                         }
                                         sensorLabelChanged(sensor.sensorId, text)
-                                        layout.state = ""
+                                        delegate.editing = false
                                     }
                                 }
                                 ToolButton {
@@ -290,6 +298,7 @@ Control {

                         states: State {
                             name: "editing"
+                            when: delegate.editing
                             PropertyChanges {
                                 target: normalLayout
                                 visible: false
-- 
2.53.0
